package dustin.cex.domains.kyc;
import dustin.cex.domains.mail.*;
import dustin.cex.domains.security.OperatorMfaService;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.*;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 실제 공개 회신·수신 선택·독립 보안키 서명과 DB로 재시도 예산의 단 한 번 확정을 검증한다. */
class CustomerMailRetryIntegrationTest extends CustomerFinalTestSupport {
    @DynamicPropertySource static void mail(DynamicPropertyRegistry r){CustomerMailTestSupport.mailProperties(r);}
    @Autowired CustomerEmailVerification email;@Autowired CustomerServiceMail serviceMail;@Autowired CustomerMailOutbox outbox;@Autowired CustomerMailDispatcher dispatcher;@Autowired CustomerMailRetryService retry;
    UUID job;
    UUID job(UUID reference){return jdbc.queryForObject("SELECT id FROM customer_mail_jobs WHERE reference_id=?",UUID.class,reference);}
    @BeforeEach void exhaustedNotice() throws Exception {
        CustomerMailTestSupport.server().purgeEmailFromAllMailboxes();CustomerMailTestSupport.server().setUser(customer.getEmail(),"sandbox-only");
        var challenge=email.request(customer.getId(),sid,UUID.randomUUID());String token=outbox.open(job(challenge.challengeId())).token();outbox.finish(outbox.claim(),"SUPPRESSED");email.confirm(customer.getId(),sid,challenge.challengeId(),token);serviceMail.choose(customer.getId(),sid,UUID.randomUUID(),true);
        var r=replies.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),note.id());job=job(r.id());
        for(int n=0;n<5;n++){outbox.finish(outbox.claim(),"SMTP_UNKNOWN");due();}
        assertEquals("EXHAUSTED",outbox.state(job).status());
    }
    @AfterEach void drain(){reset(audit);jdbc.update("UPDATE customer_mail_delivery SET lease_until=clock_timestamp()-interval '1 second' WHERE status='SENDING'");jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE status='RETRY'");for(int i=0;i<100;i++){var lease=outbox.claim();if(lease==null)break;outbox.finish(lease,"SUPPRESSED");}}
    void due(){jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_id=?",job);}
    CustomerMailRetryService.Request propose(){return retry.propose(maker.user().getId(),maker.sid(),job,UUID.randomUUID(),checker.user().getId());}
    OperatorMfaService.AuthorizationProof proof(CustomerMailRetryService.Request r,boolean approve) throws Exception {retry.inspect(checker.user().getId(),checker.sid(),r.payload().id());var o=retry.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),approve).authentication();return new OperatorMfaService.AuthorizationProof(o.challengeId(),checker.key().assertion(o,"http://localhost:3003",true,counter.incrementAndGet(),null));}
    CustomerMailRetryService.Request decide(CustomerMailRetryService.Request r,boolean yes,OperatorMfaService.AuthorizationProof proof){return retry.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),yes,proof);}
    @Test void signedApprovalKeepsOriginalEnvelopeAndIncreasesCumulativeAttempt() throws Exception {var before=outbox.open(job);var r=propose();assertEquals("APPROVED",decide(r,true,proof(r,true)).status());assertEquals("RETRY",outbox.state(job).status());assertEquals(5,outbox.state(job).attempts());dispatcher.dispatchOnce();assertEquals("SMTP_ACCEPTED",outbox.state(job).status());assertEquals(6,outbox.state(job).attempts());assertEquals(before,outbox.open(job));assertEquals("<"+job+"@exchange.test>",CustomerMailTestSupport.server().getReceivedMessages()[0].getMessageID());assertEquals(1,active());blocked();}
    @Test void extraBudgetStopsAtTenAndCannotBeGrantedTwice() throws Exception {var r=propose();decide(r,true,proof(r,true));for(int n=0;n<5;n++){outbox.finish(outbox.claim(),"SMTP_UNKNOWN");due();}assertEquals(10,outbox.state(job).attempts());assertEquals("EXHAUSTED",outbox.state(job).status());assertNull(outbox.claim());assertThrows(ResponseStatusException.class,this::propose);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_grants WHERE job_id=?",Long.class,job));}
    @Test void rejectionDoesNotReleaseAndAllowsNewRequest() throws Exception {var r=propose();assertEquals("REJECTED",decide(r,false,proof(r,false)).status());assertEquals("EXHAUSTED",outbox.state(job).status());assertNotNull(propose());}
    @Test void sameKeyReplaysAfterApprovalWithoutAnotherGrant() throws Exception {UUID key=UUID.randomUUID();var r=retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId());decide(r,true,proof(r,true));assertEquals("APPROVED",retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId()).status());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_grants WHERE job_id=?",Long.class,job));}
    @Test void pendingRequestBlocksAnotherAndChangedKeyTargetConflicts(){UUID key=UUID.randomUUID();var r=retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId());assertThrows(ResponseStatusException.class,this::propose);assertThrows(ResponseStatusException.class,()->retry.propose(maker.user().getId(),maker.sid(),job,key,nextChecker.user().getId()));assertEquals(r,retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId()));}
    @Test void ownInspectionAndExactHashAreRequired(){var r=propose();assertThrows(ResponseStatusException.class,()->retry.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));retry.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertThrows(ResponseStatusException.class,()->retry.options(checker.user().getId(),checker.sid(),r.payload().id(),"0".repeat(64),true));}
    @Test void requesterAndUnassignedCheckerCannotApprove() throws Exception {var r=propose();var p=proof(r,true);for(var a:List.of(maker,nextChecker,independent))assertThrows(ResponseStatusException.class,()->retry.decide(a.user().getId(),a.sid(),r.payload().id(),r.payloadHash(),true,p));assertEquals("APPROVED",decide(r,true,p).status());}
    @Test void oppositeDirectionProofCannotApprove() throws Exception {var r=propose();var p=proof(r,false);assertThrows(ResponseStatusException.class,()->decide(r,true,p));assertEquals("REJECTED",decide(r,false,p).status());}
    @Test void anotherBusinessProofCannotApprove() throws Exception {var r=propose();var draft=draft();var p=finalProof(draft,true);retry.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertThrows(ResponseStatusException.class,()->decide(r,true,p));assertEquals("APPROVED",decide(r,true,proof(r,true)).status());}
    @Test void changedRequesterOrCheckerVersionInvalidatesPlan() throws Exception {var r=propose();var p=proof(r,true);var u=users.findById(maker.user().getId()).orElseThrow();u.setUsername("현재 요청자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decide(r,true,p));}
    @Test void unsubscribeInvalidatesPlanAndDoesNotConsumeProof() throws Exception {var r=propose();var p=proof(r,true);serviceMail.choose(customer.getId(),sid,UUID.randomUUID(),false);assertThrows(ResponseStatusException.class,()->decide(r,true,p));assertEquals("EXHAUSTED",outbox.state(job).status());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_grants WHERE job_id=?",Long.class,job));}
    @Test void unsubscribeAfterApprovalStillSuppressesSmtp() throws Exception {var r=propose();decide(r,true,proof(r,true));serviceMail.choose(customer.getId(),sid,UUID.randomUUID(),false);dispatcher.dispatchOnce();assertEquals("SUPPRESSED",outbox.state(job).status());assertEquals(0,CustomerMailTestSupport.server().getReceivedMessages().length);}
    @Test void decisionAuditFailureRestoresProofAndGrantState() throws Exception {var r=propose();var p=proof(r,true);doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_MAIL_RETRY_DECIDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->decide(r,true,p));reset(audit);assertEquals("EXHAUSTED",outbox.state(job).status());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_grants WHERE job_id=?",Long.class,job));assertEquals("APPROVED",decide(r,true,p).status());}
    @Test void proposalAuditFailureRollsBackBindingAndCanRetry(){UUID key=UUID.randomUUID();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_MAIL_RETRY_PROPOSED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId()));reset(audit);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_requests WHERE job_id=?",Long.class,job));assertNotNull(retry.propose(maker.user().getId(),maker.sid(),job,key,checker.user().getId()));}
    @Test void concurrentDecisionsCommitOneGrant() throws Exception {var r=propose();var p=proof(r,true);var pool=Executors.newFixedThreadPool(2);try{java.util.concurrent.Callable<Boolean> act=()->{try{decide(r,true,p);return true;}catch(ResponseStatusException e){return false;}};var a=pool.submit(act);var b=pool.submit(act);assertNotEquals(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_grants WHERE job_id=?",Long.class,job));}finally{pool.shutdownNow();}}
    @Test void approvalRecordsRejectUpdateDeleteTruncate() throws Exception {var r=propose();decide(r,true,proof(r,true));for(String table:List.of("customer_mail_retry_requests","customer_mail_retry_views","customer_mail_retry_decisions","customer_mail_retry_grants"))for(String sql:List.of("UPDATE "+table+" SET job_id=job_id","DELETE FROM "+table,"TRUNCATE "+table+" CASCADE")){if(table.endsWith("views")&&sql.startsWith("UPDATE"))sql="UPDATE "+table+" SET id=id";String statement=sql;assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(statement));}}
    @Test void verificationMailCannotBeReleasedByOperators(){var id=job;UUID reference=UUID.randomUUID();job=new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->outbox.enqueue(customer.getId(),CustomerMailOutbox.Kind.EMAIL_VERIFICATION,reference,customer.getEmail(),java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[32]),Instant.now().plusSeconds(600)));for(int i=0;i<5;i++){outbox.finish(outbox.claim(),"SMTP_UNKNOWN");due();}assertThrows(ResponseStatusException.class,this::propose);job=id;}
    @Test void actualHttpRequiresDesignatedApproverAndBoundProof() throws Exception {var r=propose();var p=proof(r,true);String path="/api/admin/operations/customer-mail-retries/"+r.payload().id()+"/approve";String body=json.writeValueAsString(new CustomerMailRetryController.Decision(r.payloadHash(),p));mvc.perform(post(path).header("Authorization","Bearer "+maker.access()).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(path).header("Authorization","Bearer "+checker.access()).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED"));}
    @Test void changedCheckerVersionInvalidatesProof() throws Exception {var r=propose();var p=proof(r,true);var u=users.findById(checker.user().getId()).orElseThrow();u.setUsername("현재 승인자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decide(r,true,p));}
    @Test void changedRecipientInvalidatesProof() throws Exception {var r=propose();var p=proof(r,true);var u=users.findById(customer.getId()).orElseThrow();u.setEmail(UUID.randomUUID()+"@other.invalid");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decide(r,true,p));assertEquals("EXHAUSTED",outbox.state(job).status());}
    @Test void disabledCustomerCannotBeReleased(){var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,this::propose);}
    @Test void sameHumanAcrossTwoAccountsCannotPropose(){var u=users.findById(checker.user().getId()).orElseThrow();u.setOperatorPersonId(maker.user().getOperatorPersonId());users.saveAndFlush(u);assertThrows(ResponseStatusException.class,this::propose);}
    @Autowired dustin.cex.domains.cdd.CddCrypto retryCrypto;
    @Test void expiredSignedPlanIsReadableButCannotBeConfirmed(){
        var r=propose();UUID id=UUID.randomUUID();Instant expires=Instant.now().minusSeconds(1).truncatedTo(java.time.temporal.ChronoUnit.MICROS);
        // 과거 요청 표본을 추가한다. 원래 요청/결정/금융 이력을 수정하거나 불변 트리거를 끄지 않는다.
        var node=(tools.jackson.databind.node.ObjectNode)json.valueToTree(r.payload());node.put("id",id.toString());node.put("expiresAt",expires.toString());String raw=json.writeValueAsString(node),hash=verifier.digest(node);
        jdbc.update("INSERT INTO customer_mail_retry_requests(id,job_id,requester_id,checker_id,request_key,payload,payload_hash,payload_mac,key_id,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?)",id,job,maker.user().getId(),checker.user().getId(),UUID.randomUUID(),raw,hash,retryCrypto.fingerprint("customer-mail-retry-v1",raw),retryCrypto.keyId(),java.sql.Timestamp.from(expires));
        assertEquals("EXPIRED",retry.status(maker.user().getId(),maker.sid(),id).status());assertThrows(ResponseStatusException.class,()->retry.inspect(checker.user().getId(),checker.sid(),id));
    }
    @Test void repeatedApprovalCannotCreateSecondDecision() throws Exception {var r=propose();var p=proof(r,true);decide(r,true,p);assertThrows(ResponseStatusException.class,()->decide(r,true,p));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_retry_decisions WHERE request_id=?",Long.class,r.payload().id()));}
    @Test void wrongSessionAndAmbientTransactionCannotPropose(){assertThrows(ResponseStatusException.class,()->retry.propose(maker.user().getId(),checker.sid(),job,UUID.randomUUID(),checker.user().getId()));assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->propose()));}

}
